namespace {
    // A small hierarchy of test certificates made by another implementation: a root, an intermediate issued by the root, and two server certificates issued by the intermediate.
    constexpr const char* certificate_root = "";
    constexpr const char* certificate_intermediate = "";
    constexpr const char* certificate_leaf = "";
    constexpr const char* certificate_leaf_rsa = "";
    constexpr const char* key_leaf = "308187020100301306072A8648CE3D020106082A8648CE3D030107046D306B0201010420AA0D2C9ED42E0953FF618D821996B6237EA83F40B24260CC51EEAB1055371A78A14403420004C3DE93124C9367BB2B0DC1E97B9D3930C39AD40BC1FD2044A622F3680E1D6BA3E98962A5CDFB45A087D26261DF40B574C9C22328D8870FC6922EB3D9F3A1BD34";
    constexpr const char* key_leaf_rsa = "";

    /// @brief  Convert a string of hexadecimal characters into bytes.
    std::vector<unsigned char> hex_2_bytes(const char* hex) {
        const auto nibble = [](const char character) -> unsigned char {
            return static_cast<unsigned char>((character >= 'A') ? (character - 'A' + 10) : (character - '0'));
        };
        std::vector<unsigned char> bytes;
        for (unsigned int i = 0; (hex[i] != 0) && (hex[i + 1] != 0); i += 2) {
            bytes.push_back(static_cast<unsigned char>((nibble(hex[i]) << 4) | nibble(hex[i + 1])));
        }
        return bytes;
    }

    /// @brief  A random generator of reasonable quality with a fixed seed, which makes every handshake repeatable.
    std::function<unsigned int()> pcg_generator(const unsigned long long int seed) {
        unsigned long long int state = 0x853C49E6748FEA9Bull ^ seed;
        return [state]() mutable -> unsigned int {
            const unsigned long long int state_previous = state;
            state = state_previous * 0x5851F42D4C957F2Dull + 0xDA3E39CB94B95BDBull;
            const unsigned int state_shift_xor_shift = static_cast<unsigned int>(((state_previous >> 18u) ^ state_previous) >> 27u);
            const unsigned int rotation = static_cast<unsigned int>(state_previous >> 59u);
            return (state_shift_xor_shift >> rotation) | (state_shift_xor_shift << ((32 - rotation) & 31));
        };
    }

    // The time used to verify certificates, the start of 2027, when every test certificate is valid.
    constexpr const long long int time_now = 1798761600ll;

    /// @brief  The trusted root certificate.
    class trusted_root final {
    public:
        std::vector<unsigned char> encoded;
        gtl::x509::certificate_type parsed;

    public:
        explicit trusted_root(const char* hex = certificate_root)
            : encoded(hex_2_bytes(hex)) {
            REQUIRE(gtl::x509::parse_certificate(this->encoded.data(), this->encoded.size(), this->parsed) == true);
        }

        trusted_root(const trusted_root&) = delete;
        trusted_root& operator=(const trusted_root&) = delete;
    };

    /// @brief  The certificates and private key of a server, with either an elliptic curve key or an rsa key.
    class server_identity final {
    public:
        std::vector<unsigned char> leaf;
        std::vector<unsigned char> intermediate;
        gtl::x509::private_key_type private_key;
        const unsigned char* certificates[2] = {};
        unsigned long long int certificate_lengths[2] = {};
        const char* host = nullptr;

    public:
        explicit server_identity(const bool is_rsa)
            : leaf(hex_2_bytes(is_rsa ? certificate_leaf_rsa : certificate_leaf))
            , intermediate(hex_2_bytes(certificate_intermediate))
            , host(is_rsa ? "rsa.example.test" : "example.test") {
            const std::vector<unsigned char> key = hex_2_bytes(is_rsa ? key_leaf_rsa : key_leaf);
            REQUIRE(gtl::x509::parse_private_key(key.data(), key.size(), this->private_key) == true);
            this->certificates[0] = this->leaf.data();
            this->certificates[1] = this->intermediate.data();
            this->certificate_lengths[0] = this->leaf.size();
            this->certificate_lengths[1] = this->intermediate.size();
        }

        server_identity(const server_identity&) = delete;
        server_identity& operator=(const server_identity&) = delete;
    };

    // The bytes sent by the server of another implementation, OpenSSL 3.0, in handshakes with a client that used the random generator with these seeds.
    // Each server then sent the line "hello from the openssl server".
    struct recording_type {
        const char* description;
        unsigned long long int seed;
        bool is_rsa;
        bool allow_tls12;
        bool allow_tls13;
        unsigned int version;
        unsigned int suite;
        const char* bytes;
    };

    constexpr const recording_type recordings[] = {
        { "TLS 1.3, ecdsa, aes-128-gcm, x25519", 101, false, false, true, 0x0304, 0x1301, "" },
        { "TLS 1.3, rsa, chacha20-poly1305, x25519", 102, true, false, true, 0x0304, 0x1303, "" },
        { "TLS 1.3, ecdsa, aes-256-gcm, secp256r1", 103, false, false, true, 0x0304, 0x1302, "" },
        { "TLS 1.2, ecdsa, aes-128-gcm", 104, false, true, false, 0x0303, 0xC02B, "" },
        { "TLS 1.2, rsa, chacha20-poly1305", 105, true, true, false, 0x0303, 0xCCA8, "" },
        { "TLS 1.2, rsa, aes-256-gcm, secp384r1", 106, true, true, false, 0x0303, 0xC030, "" },
    };

    /// @brief  Move every byte of output from one end of a connection to the other.
    template <typename from_type, typename to_type>
    bool pump(from_type& from, to_type& to) {
        unsigned char buffer[1024];
        bool moved = false;
        for (unsigned long long int length = from.get_output(buffer, sizeof(buffer)); length != 0; length = from.get_output(buffer, sizeof(buffer))) {
            static_cast<void>(to.process_input(buffer, length));
            moved = true;
        }
        return moved;
    }

    /// @brief  Run a client against a server through memory until neither has anything more to send.
    void handshake(gtl::tls_client& client, gtl::tls_server& server) {
        for (unsigned int i = 0; i < 16; ++i) {
            const bool moved_client = pump(client, server);
            const bool moved_server = pump(server, client);
            if (!moved_client && !moved_server) {
                break;
            }
        }
    }

    /// @brief  Read everything that is waiting to be read as a string.
    template <typename connection_type>
    std::string read_all(connection_type& connection) {
        std::string data;
        unsigned char buffer[256];
        for (unsigned long long int length = connection.read(buffer, sizeof(buffer)); length != 0; length = connection.read(buffer, sizeof(buffer))) {
            data.append(reinterpret_cast<const char*>(buffer), length);
        }
        return data;
    }
}

TEST(tls_client, traits, standard) {
    REQUIRE((std::is_pod<gtl::tls_client>::value == false));

    REQUIRE((std::is_trivial<gtl::tls_client>::value == false));

    REQUIRE((std::is_trivially_copyable<gtl::tls_client>::value == false));

    REQUIRE((std::is_copy_constructible<gtl::tls_client>::value == false));
}

TEST(tls_client, constructor, empty) {
    gtl::tls_client client;
    REQUIRE(client.get_state() == gtl::tls_client::state_type::idle);
    REQUIRE(client.is_connected() == false);
    REQUIRE(client.get_version() == 0);
    REQUIRE(client.get_suite() == 0);
    REQUIRE(client.get_output_length() == 0);
    REQUIRE(client.get_read_length() == 0);
    REQUIRE(client.get_server_certificates().empty() == true);
    // Nothing can be done with a client that has not been started.
    const unsigned char data[4] = { 1, 2, 3, 4 };
    unsigned char buffer[16] = {};
    REQUIRE(client.process_input(data, 4) == false);
    REQUIRE(client.write(data, 4) == false);
    REQUIRE(client.read(buffer, sizeof(buffer)) == 0);
    REQUIRE(client.get_output(buffer, sizeof(buffer)) == 0);
    client.close();
    REQUIRE(client.get_state() == gtl::tls_client::state_type::idle);
}

TEST(tls_client, function, start) {
    const trusted_root root;
    gtl::tls_client::configuration_type configuration;
    configuration.host = "example.test";
    configuration.trusted = &root.parsed;
    configuration.trusted_length = 1;
    configuration.time = time_now;
    {
        // A random generator is required.
        gtl::tls_client client;
        REQUIRE(client.start(configuration) == false);
        REQUIRE(client.get_state() == gtl::tls_client::state_type::idle);
    }
    configuration.random_generator = pcg_generator(1);
    {
        // At least one version must be allowed.
        gtl::tls_client::configuration_type no_versions = configuration;
        no_versions.allow_tls12 = false;
        no_versions.allow_tls13 = false;
        gtl::tls_client client;
        REQUIRE(client.start(no_versions) == false);
    }
    {
        gtl::tls_client client;
        REQUIRE(client.start(configuration) == true);
        REQUIRE(client.get_state() == gtl::tls_client::state_type::handshake);
        // The hello message is waiting to be sent, as a single handshake record.
        REQUIRE(client.get_output_length() > 100);
        unsigned char output[1024] = {};
        const unsigned long long int length = client.get_output(output, sizeof(output));
        REQUIRE(length > 100);
        REQUIRE(client.get_output_length() == 0);
        REQUIRE(output[0] == gtl::tls_record::content_handshake);
        REQUIRE(output[5] == gtl::tls_handshake::message_client_hello);
        REQUIRE(length == (5u + (static_cast<unsigned int>(output[3]) << 8) + output[4]));
        // A client cannot be started twice.
        REQUIRE(client.start(configuration) == false);
        // Application data cannot be sent until connected.
        REQUIRE(client.write(output, 4) == false);
    }
    {
        // The same random generator gives the same hello message, and a different one gives a different message.
        unsigned char output[3][1024] = {};
        unsigned long long int lengths[3] = {};
        for (unsigned int i = 0; i < 3; ++i) {
            configuration.random_generator = pcg_generator((i == 2) ? 2 : 1);
            gtl::tls_client client;
            REQUIRE(client.start(configuration) == true);
            lengths[i] = client.get_output(output[i], sizeof(output[i]));
        }
        REQUIRE(lengths[0] == lengths[1]);
        REQUIRE(testbench::is_memory_same(output[0], output[1], lengths[0]) == true);
        REQUIRE(lengths[0] == lengths[2]);
        REQUIRE(testbench::is_memory_same(output[0], output[2], lengths[0]) == false);
    }
}

TEST(tls_client, evaluate, recorded_servers) {
    // Replay what real servers sent, which only works if every message, key, and record of the client is exactly right.
    const trusted_root root;
    for (const recording_type& recording : recordings) {
        const server_identity identity(recording.is_rsa);
        const std::vector<unsigned char> bytes = hex_2_bytes(recording.bytes);
        gtl::tls_client::configuration_type configuration;
        configuration.random_generator = pcg_generator(recording.seed);
        configuration.host = identity.host;
        configuration.trusted = &root.parsed;
        configuration.trusted_length = 1;
        configuration.time = time_now;
        configuration.allow_tls12 = recording.allow_tls12;
        configuration.allow_tls13 = recording.allow_tls13;
        // Deliver the bytes all at once, and then again one byte at a time.
        for (unsigned int pass = 0; pass < 2; ++pass) {
            gtl::tls_client client;
            REQUIRE(client.start(configuration) == true);
            if (pass == 0) {
                REQUIRE(client.process_input(bytes.data(), bytes.size()) == true, "Failed to replay '%s', alert %u.", recording.description, client.get_alert());
            }
            else {
                for (const unsigned char& byte : bytes) {
                    REQUIRE_SILENT(client.process_input(&byte, 1) == true);
                }
            }
            REQUIRE(client.is_connected() == true, "Not connected after replaying '%s', alert %u.", recording.description, client.get_alert());
            REQUIRE(client.get_version() == recording.version);
            REQUIRE(client.get_suite() == recording.suite);
            REQUIRE(read_all(client) == "hello from the openssl server\n");
            REQUIRE(client.get_server_certificates().size() == 2);
            REQUIRE(client.get_server_certificates()[0] == identity.leaf);
            REQUIRE(client.get_server_certificates()[1] == identity.intermediate);
        }

        // A client with a different random generator has different keys, so cannot use the same bytes.
        {
            configuration.random_generator = pcg_generator(recording.seed + 1000);
            gtl::tls_client client;
            REQUIRE(client.start(configuration) == true);
            REQUIRE(client.process_input(bytes.data(), bytes.size()) == false);
            REQUIRE(client.get_state() == gtl::tls_client::state_type::failed);
            REQUIRE(client.is_alert_received() == false);
            configuration.random_generator = pcg_generator(recording.seed);
        }

        // Changing any one byte of what the server sent during the handshake makes the handshake fail.
        for (unsigned long long int index = 0; index < 600; index += 13) {
            std::vector<unsigned char> changed = bytes;
            changed[index] ^= 0x04;
            gtl::tls_client client;
            REQUIRE(client.start(configuration) == true);
            static_cast<void>(client.process_input(changed.data(), changed.size()));
            REQUIRE_SILENT(client.is_connected() == false);
        }
    }
}

TEST(tls_client, evaluate, verify_server) {
    const trusted_root root;
    const trusted_root other_root(certificate_leaf_rsa);
    const server_identity identity(false);
    gtl::tls_server::configuration_type server_configuration;
    server_configuration.random_generator = pcg_generator(10);
    server_configuration.certificates = identity.certificates;
    server_configuration.certificate_lengths = identity.certificate_lengths;
    server_configuration.certificates_length = 2;
    server_configuration.private_key = &identity.private_key;

    struct case_type {
        const char* description;
        const char* host;
        const gtl::x509::certificate_type* trusted;
        unsigned int trusted_length;
        long long int time;
        bool verify_certificate;
        unsigned int certificates_length;
        bool connected;
        unsigned char alert;
    };

    const case_type cases[] = {
        { "valid", "example.test", &root.parsed, 1, time_now, true, 2, true, 0 },
        { "valid for a wildcard name", "www.wild.example.test", &root.parsed, 1, time_now, true, 2, true, 0 },
        { "valid with no host to check", nullptr, &root.parsed, 1, time_now, true, 2, true, 0 },
        { "the wrong host", "other.test", &root.parsed, 1, time_now, true, 2, false, gtl::tls_handshake::alert_bad_certificate },
        { "no trusted certificates", "example.test", nullptr, 0, time_now, true, 2, false, gtl::tls_handshake::alert_unknown_authority },
        { "an unrelated trusted certificate", "example.test", &other_root.parsed, 1, time_now, true, 2, false, gtl::tls_handshake::alert_unknown_authority },
        { "the intermediate is not sent", "example.test", &root.parsed, 1, time_now, true, 1, false, gtl::tls_handshake::alert_unknown_authority },
        { "after the certificate expires", "example.test", &root.parsed, 1, 2019686401ll, true, 2, false, gtl::tls_handshake::alert_certificate_expired },
        { "before the certificate is valid", "example.test", &root.parsed, 1, 1704067199ll, true, 2, false, gtl::tls_handshake::alert_certificate_expired },
        { "nothing is verified", "other.test", nullptr, 0, 0, false, 1, true, 0 },
    };
    for (const case_type& test : cases) {
        for (unsigned int version = 0; version < 2; ++version) {
            gtl::tls_client::configuration_type configuration;
            configuration.random_generator = pcg_generator(11);
            configuration.host = test.host;
            configuration.trusted = test.trusted;
            configuration.trusted_length = test.trusted_length;
            configuration.time = test.time;
            configuration.verify_certificate = test.verify_certificate;
            configuration.allow_tls13 = (version == 0);
            server_configuration.certificates_length = test.certificates_length;
            gtl::tls_client client;
            gtl::tls_server server;
            REQUIRE(server.start(server_configuration) == true);
            REQUIRE(client.start(configuration) == true);
            handshake(client, server);
            REQUIRE(client.is_connected() == test.connected, "Unexpected result for '%s', alert %u.", test.description, client.get_alert());
            REQUIRE(client.get_version() == ((version == 0) ? 0x0304u : 0x0303u));
            if (test.connected) {
                REQUIRE(server.is_connected() == true);
            }
            else {
                // The client tells the server why it gave up.
                REQUIRE(client.get_state() == gtl::tls_client::state_type::failed);
                REQUIRE(client.get_alert() == test.alert, "Unexpected alert %u for '%s'.", client.get_alert(), test.description);
                REQUIRE(client.is_alert_received() == false);
                REQUIRE(server.get_state() == gtl::tls_server::state_type::failed);
                REQUIRE(server.get_alert() == test.alert);
                REQUIRE(server.is_alert_received() == true);
            }
        }
    }
}

TEST(tls_client, evaluate, exchange) {
    const trusted_root root;
    const server_identity identity(true);
    gtl::tls_server::configuration_type server_configuration;
    server_configuration.random_generator = pcg_generator(20);
    server_configuration.certificates = identity.certificates;
    server_configuration.certificate_lengths = identity.certificate_lengths;
    server_configuration.certificates_length = 2;
    server_configuration.private_key = &identity.private_key;
    gtl::tls_client::configuration_type configuration;
    configuration.random_generator = pcg_generator(21);
    configuration.host = identity.host;
    configuration.trusted = &root.parsed;
    configuration.trusted_length = 1;
    configuration.time = time_now;
    gtl::tls_client client;
    gtl::tls_server server;
    REQUIRE(server.start(server_configuration) == true);
    REQUIRE(client.start(configuration) == true);
    handshake(client, server);
    REQUIRE(client.is_connected() == true);
    REQUIRE(server.is_connected() == true);

    // Data in both directions, including more than one record can hold.
    const std::string request = "a request from the client";
    std::string response;
    for (unsigned int i = 0; i < 50000; ++i) {
        response.push_back(static_cast<char>('a' + (i % 26)));
    }
    REQUIRE(client.write(reinterpret_cast<const unsigned char*>(request.data()), request.size()) == true);
    REQUIRE(pump(client, server) == true);
    REQUIRE(server.get_read_length() == request.size());
    REQUIRE(read_all(server) == request);
    REQUIRE(server.write(reinterpret_cast<const unsigned char*>(response.data()), response.size()) == true);
    REQUIRE(pump(server, client) == true);
    REQUIRE(client.get_read_length() == response.size());
    REQUIRE(read_all(client) == response);
    REQUIRE(client.write(nullptr, 0) == true);
    REQUIRE(client.get_output_length() == 0);

    // Closing tells the server, which closes in reply, and data that was already received can still be read.
    REQUIRE(server.write(reinterpret_cast<const unsigned char*>(request.data()), request.size()) == true);
    REQUIRE(pump(server, client) == true);
    client.close();
    REQUIRE(client.get_state() == gtl::tls_client::state_type::closed);
    REQUIRE(client.write(reinterpret_cast<const unsigned char*>(request.data()), request.size()) == false);
    REQUIRE(pump(client, server) == true);
    REQUIRE(server.get_state() == gtl::tls_server::state_type::closed);
    REQUIRE(server.write(reinterpret_cast<const unsigned char*>(request.data()), request.size()) == false);
    static_cast<void>(pump(server, client));
    REQUIRE(read_all(client) == request);
    REQUIRE(client.get_state() == gtl::tls_client::state_type::closed);
}

namespace {
    // The sample client below shows how to use the tls_client class with a socket and the http class, which together make an https client.
    // It can be tried against the sample server in the tests of the tls_server class, or against other programs.
    // By default the server only serves a client that is already trying to connect, and the client only tries to connect once, so that the tests do not wait.
    // Set this to true, here and in the tests of the tls_server class, to make the server wait for a client, and the client wait for a server.
    // The server then also writes its certificate to a file, so that other programs can be told to trust it:
    //     curl --cacert gtl_sample_certificate.pem https://localhost:48443/hello
    constexpr const bool sample_wait = false;

    // The longest time that the sample server and client wait for each other.
    constexpr const unsigned int sample_wait_seconds = 60;

    // The port of the sample server.
    constexpr const unsigned short sample_port = 48443;

    /// @brief  The private key and certificate of the sample server, which are made here rather than loaded from files.
    /// @note   The private key is fixed so that the sample client can make the same certificate and trust it.
    /// @note   A real server must make its private key from an unpredictable source of random numbers, and keep it secret.
    class sample_identity final {
    public:
        gtl::x509::private_key_type private_key;
        std::vector<unsigned char> certificate;

    public:
        sample_identity() {
            // An elliptic curve private key is just a number, here one whose bytes count up in sevens.
            this->private_key.algorithm = gtl::x509::key_algorithm::secp256r1;
            for (unsigned int i = 0; i < 32; ++i) {
                this->private_key.scalar[i] = static_cast<unsigned char>((i * 7) + 1);
            }
            gtl::x509::public_key_type public_key;
            REQUIRE(gtl::x509::get_public_key(this->private_key, public_key) == true);

            // A certificate for the names that clients use to reach the server, valid from the start of 2026 to the start of 2036, signed with its own key.
            const unsigned char serial_number[1] = { 0x01 };
            const char* hosts[2] = { "localhost", "127.0.0.1" };
            gtl::x509::description_type description;
            description.subject.organisation = "gtl";
            description.subject.common_name = "localhost";
            description.serial_number = serial_number;
            description.serial_number_length = sizeof(serial_number);
            description.not_before = 1767225600ll;
            description.not_after = 2082758400ll;
            description.hosts = hosts;
            description.hosts_length = 2;
            this->certificate.resize(1024);
            unsigned long long int length = 0;
            // An elliptic curve key needs no random numbers to sign, so no random generator is given.
            REQUIRE(gtl::x509::generate_certificate(description, public_key, this->private_key, gtl::x509::signature_scheme::ecdsa_sha2_256, std::function<unsigned int()>(), this->certificate.data(), this->certificate.size(), length) == true);
            this->certificate.resize(length);
        }

        sample_identity(const sample_identity&) = delete;
        sample_identity& operator=(const sample_identity&) = delete;
    };

    /// @brief  Move bytes between a socket and a tls_client or tls_server, once in each direction.
    /// @return false when the socket has closed.
    template <typename tls_type>
    bool sample_pump(const gtl::socket& socket, tls_type& tls) {
        unsigned char buffer[4096];
        while (tls.get_output_length() != 0) {
            const unsigned long long int length = tls.get_output(buffer, sizeof(buffer));
            for (unsigned long long int sent = 0; sent < length;) {
                const long long int count = socket.tcp_send(buffer + sent, length - sent);
                if (count < 0) {
                    return false;
                }
                sent += static_cast<unsigned long long int>(count);
            }
        }
        const long long int count = socket.tcp_receive(buffer, sizeof(buffer));
        if (count < 0) {
            return false;
        }
        if (count == 0) {
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
        static_cast<void>(tls.process_input(buffer, static_cast<unsigned long long int>(count)));
        return true;
    }

    /// @brief  Read the application data that is waiting on a tls_client or tls_server, adding it to a string.
    template <typename tls_type>
    void sample_read(tls_type& tls, std::string& data) {
        unsigned char buffer[4096];
        for (unsigned long long int length = tls.read(buffer, sizeof(buffer)); length != 0; length = tls.read(buffer, sizeof(buffer))) {
            data.append(reinterpret_cast<const char*>(buffer), length);
        }
    }
}

TEST(tls_client, sample, client) {
    // The certificate to trust, here the certificate of the sample server itself, it could instead be the certificate of the authority that issued it.
    const sample_identity identity;
    gtl::x509::certificate_type trusted;
    REQUIRE(gtl::x509::parse_certificate(identity.certificate.data(), identity.certificate.size(), trusted) == true);

    // The random numbers of a connection must be unpredictable.
    std::random_device random;
    gtl::tls_client::configuration_type configuration;
    configuration.random_generator = [&random]() -> unsigned int {
        return static_cast<unsigned int>(random());
    };
    configuration.host = "localhost";
    configuration.trusted = &trusted;
    configuration.trusted_length = 1;
    configuration.time = static_cast<long long int>(std::time(nullptr));

    // Connect to the server, trying again until there is one.
    gtl::socket connection;
    std::chrono::steady_clock::time_point deadline = std::chrono::steady_clock::now() + std::chrono::seconds(sample_wait ? sample_wait_seconds : 0);
    bool opened = false;
    do {
        opened = connection.open(gtl::socket::tcp_client{ gtl::socket::ip_any, gtl::socket::port_any, gtl::socket::ip_loopback, sample_port });
        if (!opened && sample_wait) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    } while (!opened && (std::chrono::steady_clock::now() < deadline));
    if (!opened) {
        // There is only a server when one is waiting in the tests of the tls_server class.
        return;
    }

    // The tls_client is given what arrives on the socket and gives back what to send, starting with the handshake.
    gtl::tls_client tls;
    REQUIRE(tls.start(configuration) == true);
    deadline = std::chrono::steady_clock::now() + std::chrono::seconds(10);
    bool is_open = true;
    while (is_open && (tls.get_state() == gtl::tls_client::state_type::handshake) && (std::chrono::steady_clock::now() < deadline)) {
        is_open = sample_pump(connection, tls);
    }
    if (tls.get_state() == gtl::tls_client::state_type::handshake) {
        // The server went away before the handshake finished, as the sample server does when it is not waiting.
        PRINT("The sample client lost its connection to the server during the handshake.\n");
        return;
    }
    REQUIRE(tls.is_connected() == true, "The handshake of the sample client failed with alert %u.", static_cast<unsigned int>(tls.get_alert()));
    if (!tls.is_connected()) {
        return;
    }

    gtl::http::request_type request;
    request.target = "/hello";
    request.headers.push_back(gtl::http::header_type{ "Host", "localhost" });
    request.headers.push_back(gtl::http::header_type{ "Connection", "close" });
    std::string encoded;
    REQUIRE(gtl::http::write_request(request, encoded) == true);
    REQUIRE(tls.write(reinterpret_cast<const unsigned char*>(encoded.data()), encoded.size()) == true);

    // Read until there is a whole response, which may be ended by the server closing the connection.
    std::string received;
    gtl::http::response_type response;
    unsigned long long int response_length = 0;
    gtl::http::result_type result = gtl::http::result_type::incomplete;
    bool is_closed = false;
    while ((result == gtl::http::result_type::incomplete) && !is_closed && (std::chrono::steady_clock::now() < deadline)) {
        is_closed = !sample_pump(connection, tls) || (tls.get_state() != gtl::tls_client::state_type::connected);
        sample_read(tls, received);
        result = gtl::http::read_response(received.data(), received.size(), is_closed, false, response, response_length);
    }
    REQUIRE(result == gtl::http::result_type::complete);
    PRINT("The sample client received, using version %04X and cipher suite %04X: %u %s\n%s", tls.get_version(), tls.get_suite(), response.status, response.reason.c_str(), response.body.c_str());
    REQUIRE(response.status == 200);
    REQUIRE(response.body == "Hello from the gtl https server, you asked for /hello\n");
}
